values
  ('57bbbb18-d71f-5552-a885-f24ca7fcc93b', null, (select id from public.skills where slug = 'read-g12-figurative-language'), null, 'hard',
   $q$On the walk home, Lucia "felt oddly deflated." Why does "deflated" fit better here than a near synonym such as "defeated"?$q$, $q$[{"text":"\"Deflated\" suggests anger at Ms. Haddad, while \"defeated\" suggests calm.","is_correct":false,"misconception_token":"misreads-tone"},{"text":"\"Deflated\" and \"defeated\" mean the same, so the choice changes nothing.","is_correct":false,"misconception_token":"ignores-connotation"},{"text":"\"Deflated\" means she was physically tired from walking a long way.","is_correct":false,"misconception_token":"literal-reading"},{"text":"\"Deflated\" suggests a mild loss of self-importance, not a real failure.","is_correct":true}]$q$::jsonb, $q$"Deflated" suggests a mild loss of self-importance, not a real failure.$q$, $q$Lucia's pride in being "the bridge" shrank when the drawing worked without her, the way a balloon loses air; "defeated" would imply she had lost a contest or truly failed. The instructions were understood, so nothing was lost, and she shows no anger at Ms. Haddad.$q$, 'draft', '86b331d4-0106-5eee-abe8-a5909b2a91ff')
