  ('ac4fd105-0bf7-5d63-92ef-0def666e2f33', null, (select id from public.skills where slug = 'read-g12-figurative-language'), null, 'medium',
   $q$Kwame checked the weather app "as if staring at it hard enough might push the clouds aside." What does this comparison reveal about him?$q$, $q$[{"text":"He is calm and expects the weather to clear without any worry.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He believes the app can control the weather if used correctly.","is_correct":false,"misconception_token":"literal-reading"},{"text":"He is frustrated and wishes he could force the sky to clear.","is_correct":true},{"text":"He is bored and only checks his phone to pass the time.","is_correct":false,"misconception_token":"misreads-tone"}]$q$::jsonb, $q$He is frustrated and wishes he could force the sky to clear.$q$, $q$The comparison shows a wish for control he does not have, matching his pacing and his announcement that it is "a disaster." The "as if" signals he does not literally believe the app can move clouds.$q$, 'draft', '644ac0f9-9f8b-5995-bbe1-d02e8ddd4f9b')
